const dictionaries: Record<Language, Dictionary> = { en, ru };
export function translationCoverage(): { missingInEnglish: string[]; missingInRussian: string[] } {
  const enKeys = new Set(Object.keys(en));
  const ruKeys = new Set(Object.keys(ru));
  return {
    missingInEnglish: [...ruKeys].filter(key => !enKeys.has(key)).sort(),
    missingInRussian: [...enKeys].filter(key => !ruKeys.has(key)).sort(),
  };
}
const I18nContext = createContext<{ language: Language; t: (key: string) => string }>({ language: "en", t: key => en[key] ?? key });
export function I18nProvider({ language, children }: { language: Language; children: ReactNode }) {
  const dictionary = dictionaries[language] ?? en;
  return <I18nContext.Provider value={{ language, t: key => dictionary[key] ?? en[key] ?? key }}>{children}</I18nContext.Provider>;
}
export function useI18n() { return useContext(I18nContext); }
export function translatedValue(t: (key: string) => string, prefix: string, value: string): string {
  const key = `${prefix}.${value}`;
  const translated = t(key);
  return translated === key ? value : translated;
}
